-- (chay SELECT nay sau commit; ky tu tieng Viet co dau)
commit;

select count(*) as dong_con_tieng_viet from crm_deals
where quoc_gia is distinct from 'VN'
  and concat_ws(' ', ten, cdt_text, tvtk_text, thau_text, dia_diem, hang_muc, giai_doan, moc_spec_in, uu_tien) ~ '[À-Ỹà-ỹ]';
